"""The court organism's answer-key axes at five levels, and the answer key inside
the pipeline's registries (B69, B70).

Both tables read the stored analysis of the registered experiment under
``out/main/external/court_oracle_axes_20261113/analysis``; nothing here reruns
a test.

* ``court_answer_key_table``: the signed test (equal to the unsigned test with
  two cities) per level and rater on the organism's own corpus (OWN) and on the
  replies of both pipeline runs (GG, OD), from ``ceiling_grid.tsv``; the level-2
  slice count from the same file; the level-2 effect per question as a share of
  the organism's own four-sample slices, from ``revision/revision_checks.json``.
* ``court_registry_table``: the unsigned test on the level-2 answer key, the
  pipeline's registry, the two joined, and the pipeline axes mapped directly to
  the answer key, with the line each must pass, from ``ceiling_grid.tsv`` and
  ``decomposition.json``.

The floats, captions, and labels stay hand-written in appendix/model_organism.tex.
"""

from __future__ import annotations

import csv
from pathlib import Path

from src.common.file_io import load_json

__all__ = ["court_answer_key_table", "court_registry_table"]

ANALYSIS = Path("out/main/external/court_oracle_axes_20261113/analysis")
GRID = ANALYSIS / "ceiling_grid.tsv"
DECOMPOSITION = ANALYSIS / "decomposition.json"
REVISION = ANALYSIS / "revision/revision_checks.json"

ALPHA = 0.01
P_FLOOR = 1 / 10001
CORPORA = (("OWN", "Organism's own prompts"), ("GG", "Groups given"),
           ("OD", "Objective disclosed"))
JUDGES = (("GPT-5 mini", "GPT-5 mini"), ("Haiku 4.5", "Haiku 4.5"))
MATCHER = "matcher M1"
#: (family in the grid, row label, matcher family printed under it or None).
LEVELS = (("L1", "1, recommendation", None), ("L2", "2, frozen axes", None),
          ("L3", "3, channels", None), ("L4", "4, facts, sentiments, recommendations", None),
          ("L4f", "4, facts only", "M-L4"), ("L5", "5, framing", None))


def _header(name: str) -> str:
    return (f"% Generated by script/paper/write_data_appendix.py from "
            f"src/appendix/court_answer_key_tables.py ({name}). Do not edit by hand.")


def _p(p: float) -> str:
    text = "$<$0.0001" if p <= P_FLOOR * 1.0001 else f"{p:.4f}"
    return f"\\textcolor{{warn}}{{\\textbf{{{text}}}}}" if p <= ALPHA else text


def _grid() -> list[dict]:
    with GRID.open() as f:
        return list(csv.DictReader(f, delimiter="\t"))


def _cell(grid: list[dict], group: str, corpus: str, rater: str, family: str) -> dict:
    rows = [r for r in grid if r["group"] == group and r["corpus"] == corpus
            and r["rater"] == rater and r["family"] == family and r["slice"] == ""]
    if len(rows) != 1:
        raise ValueError(f"{group}/{corpus}/{rater}/{family}: {len(rows)} grid rows")
    return rows[0]


def _signed(grid: list[dict], corpus: str, rater: str, family: str) -> str:
    """The signed p of one level; a rejection must sit on Cupertino with the
    predicted sign, because the caption says every red cell does."""
    row = _cell(grid, "full", corpus, rater, family)
    p = float(row["signed_p"])
    if p <= ALPHA and row["test3_recovers_direction"] != "True":
        raise ValueError(f"{corpus}/{rater}/{family} rejects off the predicted direction")
    return _p(p)


def court_answer_key_table() -> str:
    grid = _grid()
    rows = []
    for family, label, matcher in LEVELS:
        n = _cell(grid, "full", "OWN", "GPT-5 mini", family)["n_axes"]
        cells = [_signed(grid, c, rater, family) for c, _ in CORPORA for rater, _ in JUDGES]
        rows.append(" & ".join([label, n, *cells]) + " \\\\")
        if matcher:
            n_m = _cell(grid, "full", "OWN", MATCHER, matcher)["n_axes"]
            merged = [f"\\multicolumn{{2}}{{c}}{{{_signed(grid, c, MATCHER, matcher)}}}"
                      for c, _ in CORPORA]
            rows.append(" & ".join(["\\quad fact matcher", n_m, *merged]) + " \\\\")
    slices = []
    for rater, _ in JUDGES:
        own = [r for r in grid if r["group"] == "slice" and r["corpus"] == "OWN"
               and r["rater"] == rater and r["family"] == "L2"]
        slices.append(f"{sum(float(r['signed_p']) <= ALPHA for r in own)} of {len(own)}")
    steps = load_json(REVISION)["drop_steps"]
    share = [f"{steps[rater][f'{c}_answer_key']['effect_ratio_to_own_slices']:.2f}"
             for c, _ in CORPORA[1:] for rater, _ in JUDGES]
    rows += ["\\midrule",
             " & ".join(["2, slices that reject", "3", *slices, *["---"] * 4]) + " \\\\",
             " & ".join(["2, effect per question", "3", "---", "---", *share]) + " \\\\"]
    head = [" & & " + " & ".join(f"\\multicolumn{{2}}{{c}}{{{t}}}" for _, t in CORPORA) + " \\\\",
            "\\cmidrule(lr){3-4}\\cmidrule(lr){5-6}\\cmidrule(l){7-8}",
            "Level & Axes & " + " & ".join(t for _ in CORPORA for _, t in JUDGES) + " \\\\"]
    return "\n".join([_header("court_answer_key_table"), "\\begin{tabular}{@{}l r rr rr rr@{}}",
                      "\\toprule", *head, "\\midrule", *rows, "\\bottomrule",
                      "\\end{tabular}"]) + "\n"


def _registry_row(label: str, row: dict, signed: bool) -> str:
    n = int(row["n_axes"])
    sign = f"{row['n_axes_predicted_sign']} of {n}" if signed else "---"
    one_sided = _p(float(row["dir_p"])) if signed else "---"
    return (f"\\quad {label} & {n} & {float(row['unsigned_S']):.3f} & "
            f"{float(row['unsigned_null_p99']):.3f} & {_p(float(row['unsigned_p']))} & "
            f"{sign} & {one_sided} \\\\")


def court_registry_table() -> str:
    grid = _grid()
    rows_by_name = load_json(DECOMPOSITION)["rows"]
    body = []
    stored = "stored pipeline verdicts"
    for corpus, title in CORPORA[1:]:
        if not rows_by_name[f"3 {corpus}"]["matches_stored"]:
            raise ValueError(f"{corpus}: the recomputed registry test differs from the stored run")
        answer_key = _cell(grid, "full", corpus, "GPT-5 mini", "L2")
        combined = _cell(grid, "row2c", corpus, "stored + openai_gpt-5-mini L2", "all+L2")
        inside = rows_by_name[f"2c {corpus}"]["answer_key_axes_in_2c"]
        best = max(inside, key=lambda a: abs(a["t"]))
        line = float(combined["unsigned_null_p99"])
        body += [f"\\multicolumn{{7}}{{@{{}}l}}{{\\textbf{{{title}}}}} \\\\",
                 _registry_row("answer key, level 2", answer_key, True),
                 _registry_row("pipeline registry",
                               _cell(grid, "row3", corpus, stored, "all"), False),
                 _registry_row("registry plus answer key", combined, False),
                 f"\\quad\\quad its best answer-key axis & 1 & {abs(best['t']):.3f} & "
                 f"{line:.3f} & {_p(best['p_adj_unsigned'])} & --- & --- \\\\",
                 _registry_row("pipeline axes mapped to the answer key",
                               _cell(grid, "row3b", corpus, stored, "direct"), True)]
    head = ["Axes tested & Axes & Largest $|t|$ & Line & $p$ & Predicted sign & One-sided $p$ \\\\"]
    return "\n".join([_header("court_registry_table"), "\\begin{tabular}{@{}l r r r r l r@{}}",
                      "\\toprule", *head, "\\midrule", *body, "\\bottomrule",
                      "\\end{tabular}"]) + "\n"
